import { test, expect } from '@playwright/test';
import { e2eTenantId, getApiContext, setupTenant } from './fixtures';

test.describe('Proactive Context-Aware Task Suggestions', () => {
  let tenantId: string;

  test.beforeAll(async () => {
    tenantId = await setupTenant();
  });

  test('Owner sees proactive insight card and can approve it', async ({ page }) => {
    const api = getApiContext();

    // Mock a proactive insight generated by the backend worker
    await api.post('/api/dev/seed', {
        data: {
            scenario: 'proactive-insight',
            tenantId
        }
    });

    await page.goto(`/dashboard?tenant=${tenantId}`);

    // Verify the "Needs Attention Today" card is visible
    const insightCard = page.getByTestId(/proactive-insight-.+/);
    await expect(insightCard).toBeVisible({ timeout: 15000 });

    await expect(insightCard.getByText('Needs Attention Today')).toBeVisible();

    // Click "Approve"
    const approveBtn = insightCard.getByTestId('approve-insight');
    await expect(approveBtn).toBeVisible();
    await approveBtn.click();

    // Verify the card is dismissed
    await expect(insightCard).toBeHidden({ timeout: 10000 });
  });
});
